for layer in ['corrected','English']:
 for n,term,crop in [('5','universal derivation','canonical-derivation'),('3','principal-parts ring','principal-parts')]:
  ch(layer,f'(I 1.1.2.{n})',f'(II 1.1.2.{n})','definition reference','III.p157.chapter-reference-'+n,f'The print has I, but the cited {term} is II1.1.2.{n} on printed115, reinspected in evidence/I_p115_{crop}.png. ChapterII begins on114; these definitions, not ChapterI, provide exactly the objects used here. Keep I in the diplomatic layer.','misprint of the original')
for layer in LAYERS:
 old=region(layer);assert old.count(r'\ReflowBodyFont ')==2
