 ch(layer,r'\node at (338,3.36) {$,$};',r'\node[anchor=base] at ([xshift=12bp]Zb.base) {$,$};','1.1.6.4 comma','III.p157.diagram-comma','Place the terminal comma on the lower row baseline; preserve the centered tag, six horizontal arrows, three downward arrows and both id labels.')
 old=region(layer);assert old.count(r'\textsuperscript{(1)}')==2
 new=old.replace(r'\textsuperscript{(1)}',r'(\textsuperscript{1})').replace(r'différentielles(\textsuperscript{1})',r'différentielles (\textsuperscript{1})').replace(r'differentials(\textsuperscript{1})',r'differentials (\textsuperscript{1})')
 ch(layer,old,new,'note call and label','III.p157.footnote-parentheses','Restore baseline parentheses around the raised1 in both places, with the printed space before the body call.')
 old=region(layer)
 if layer=='English':new=old.replace('calculation\\par\n\n\\noindent\\hspace*{-0.5bp}{sketched here is shorter.}\\par','calculation sketched here is shorter.\\par')
 else:new=old.replace('calcul\\par\n\n\\noindent\\hspace*{-0.5bp}{direct esquissé ici est plus court.}\\par','calcul direct esquissé ici est plus court.\\par')
 assert new!=old
 new=new.replace(r'\vspace{3.08bp}',r'\vfill'+'\n'+r'\vspace{3.08bp}')
 ch(layer,old,new,'footnote','III.p157.footnote-flow','Join the artificial break inside the one footnote sentence and keep it at the foot of the page.','structure')
 old=region(layer);ch(layer,old,old+r'\clearpage'+'\n','page boundary','III.p157.boundary','Retain the printed page boundary.','structure')
